<section class="admin-card"><h2>Değerlendirme yönetimi</h2><p>Yorumlar fiziksel olarak silinmez. Yayınlanan yorumda müşterinin yalnızca başharfi gösterilir.</p><?php if(!$reviews): ?><p>Henüz değerlendirme yok.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th scope="col">Randevu / hizmet</th><th scope="col">Müşteri</th><th scope="col">Değerlendirme</th><th scope="col">Yayın durumu</th><th scope="col">İşlem</th></tr></thead><tbody><?php foreach($reviews as$r): ?><tr><td>#<?= (int)$r['appointment_id'] ?> · <?= e($r['service_name']) ?></td><td><?= e($r['customer_name']) ?></td><td><?= (int)$r['rating'] ?> / 5<br><?= e($r['comment']) ?></td><td><?= $r['is_visible']?'Yayında':'Gizli' ?></td><td><form method="post" action="<?= e(url('admin/reviews/visibility')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="visible" value="<?= $r['is_visible']?'0':'1' ?>"><button class="btn btn-outline-dark" type="submit"><?= $r['is_visible']?'Gizle':'Yayınla' ?></button></form></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
